113	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
114	  const task = parseYaml(
115	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
116	  ) as { repo: string };
117	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
118	  return task.repo;
119	}
