/**
 * Shared reap loop — drains completed executions from the broker,
 * routes by handle.kind, and dispatches side-effects.
 *
 * Called once per orchestrator cycle after the claim and review-fix
 * concerns have submitted their work. Any orchestrator can drain any
 * completion — dispatch is opportunistic, not pinned to the submitter.
 *
 * Routing:
 *   kind=impl       → dispatchExecutorResult (task YAML mutation)
 *   kind=review-fix → emit review_dispatch_complete event
 *
 * Error handling: individual dispatch errors are emitted as events and
 * the item is nacked (returned to the queue). Non-throwing.
 */

import { existsSync } from "node:fs";
import type { CompletionBrokerPort } from "@workflow/runtime-abi";
import { dispatchExecutorResult } from "../side-effects/dispatch.js";
import { dispatchReviewResult, type ReviewResult } from "../side-effects/dispatch-review-result.js";
import { readTask } from "../utils/task-yaml-io.js";
import { taskYamlAbsPath } from "../paths.js";
import {
  resolveRepoGitUrl,
  resolveRepoBaseBranch,
} from "../config/workspace-config.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ReapLoopOptions {
  broker: CompletionBrokerPort;
  /** All workspace roots pulled this cycle — used to locate the task YAML. */
  workspaceRoots: string[];
  /** Visibility-lock duration for peek-and-lock. Default: 30 000 ms. */
  lockMs?: number;
  /** Max completions to drain per call. Default: 10. */
  max?: number;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  githubToken: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface ReapLoopResult {
  /** Completions successfully dispatched and acked. */
  dispatched: number;
  /** Completions that failed to dispatch (nacked, will be retried). */
  failed: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Find the workspace root whose tasks directory contains the given task YAML.
 * Returns undefined if the task is not found in any pulled workspace.
 */
function findWorkspaceRoot(
  workspaceRoots: string[],
  featureId: string,
  taskId: string,
): string | undefined {
  for (const root of workspaceRoots) {
    try {
      if (existsSync(taskYamlAbsPath(root, featureId, taskId))) return root;
    } catch {
      // ignore fs errors
    }
  }
  return undefined;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Drain the broker completion queue once and dispatch each completion.
 * Non-throwing: all errors are emitted and nacked.
 */
export async function runReapLoop(opts: ReapLoopOptions): Promise<ReapLoopResult> {
  const {
    broker,
    workspaceRoots,
    lockMs = 30_000,
    max = 10,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    githubToken,
    emit,
  } = opts;

  const completions = await broker.listCompleted({ max, lockMs });
  let dispatched = 0;
  let failed = 0;

  for (const completion of completions) {
    const { handle, result, metadata } = completion;
    const { kind, task_id: taskId, feature_id: featureId } = metadata;

    try {
      const workspaceRoot = findWorkspaceRoot(workspaceRoots, featureId, taskId);
      if (!workspaceRoot) {
        emit({
          type: "reap_workspace_not_found",
          handle,
          task_id: taskId,
          feature_id: featureId,
        });
        await broker.nack(handle);
        failed++;
        continue;
      }

      const taskBranch = `feature/${featureId}-${taskId}`;

      if (kind === "impl") {
        const task = readTask(workspaceRoot, featureId, taskId);
        const taskRepoUrl = resolveRepoGitUrl(workspaceRoot, task.repo);
        const taskBaseBranch = resolveRepoBaseBranch(workspaceRoot, task.repo);

        await dispatchExecutorResult({
          result,
          workspaceRoot,
          featureId,
          taskId,
          taskBranch,
          taskTitle: task.title,
          taskRepoUrl,
          taskBaseBranch,
          githubToken,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          emit,
        });

        emit({
          type: "executor_result",
          task_id: taskId,
          feature_id: featureId,
          terminal_status: result.terminal_status,
        });
      } else if (kind === "review-fix") {
        emit({
          type: "review_dispatch_complete",
          task_id: taskId,
          feature_id: featureId,
          subkind: metadata.subkind ?? "respond",
          outcome: result.terminal_status,
          handle,
        });
      } else if (kind === "review") {
        await dispatchReviewResult({
          result: result as unknown as ReviewResult,
          workspaceRoot,
          featureId,
          taskId,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          emit,
        });
      }

      await broker.ack(handle);
      emit({
        type: "reap_acked",
        handle,
        task_id: taskId,
        feature_id: featureId,
        kind,
        terminal_status: result.terminal_status,
      });
      dispatched++;
    } catch (e) {
      emit({
        type: "reap_dispatch_error",
        handle,
        task_id: taskId,
        feature_id: featureId,
        kind,
        details: String(e),
      });
      try {
        await broker.nack(handle);
      } catch {
        // best-effort nack
      }
      failed++;
    }
  }

  return { dispatched, failed };
}

