describe("dispatchExecutorResult — max-turns retry", () => {
  async function setupWorkspace(retriedCount: number): Promise<{ wsDir: string; task: Task }> {
    const retryLog = Array.from({ length: retriedCount }, (_, i) => ({
      action: "retried",
      by: "bot@test.com",
      at: `2026-0${i + 1}-01T00:00:00Z`,
    }));
    const task = makeTask({ status: "blocked", log: retryLog as Task["log"] });
    const wsDir = makeWorkspace([task]);
    return { wsDir, task };
