    });

    expect(events.some((e) => e.type === "task_retried")).toBe(true);
    expect(events.some((e) => e.type === "task_max_retries_exceeded")).toBe(false);
  });

  it("emits task_max_retries_exceeded when at max retries (3)", async () => {
    const { wsDir, task } = await setupWorkspace(3);
    const { spawnSync: spMock } = await import("node:child_process");
    vi.mocked(spMock).mockReturnValue(mockGitShow(task));

    const { dispatchExecutorResult } = await import("../src/side-effects/dispatch.js");
    const events: Record<string, unknown>[] = [];

    await dispatchExecutorResult({
      result: { terminal_status: "blocked", blocked_reason: "max_turns_exceeded" },
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: `feature/${FEATURE_ID}-${TASK_ID}`,
      taskTitle: "Test Task",
      taskRepoUrl: "https://github.com/testorg/my-repo.git",
      taskBaseBranch: "main",
      githubToken: "ghp_test",
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "task_max_retries_exceeded")).toBe(true);
    expect(events.some((e) => e.type === "task_retried")).toBe(false);
  });

  it("does not emit retry events for non-max_turns blocked reason", async () => {
    const wsDir = makeWorkspace([makeTask({ status: "blocked" })]);
    const { execSync, spawnSync: spMock } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchExecutorResult } = await import("../src/side-effects/dispatch.js");
    const events: Record<string, unknown>[] = [];

    try {
      await dispatchExecutorResult({
        result: { terminal_status: "blocked", blocked_reason: "skill_missing" },
        workspaceRoot: wsDir,
        featureId: FEATURE_ID,
        taskId: TASK_ID,
        taskBranch: `feature/${FEATURE_ID}-${TASK_ID}`,
        taskTitle: "Test Task",
