        taskBaseBranch: "main",
        githubToken: "ghp_test",
        gitAuthorEmail: "bot@test.com",
        emit: (e) => events.push(e),
      });
    } catch { /* mutateTaskYaml may fail on fake paths */ }

    expect(events.some((e) => e.type === "task_retried")).toBe(false);
    expect(events.some((e) => e.type === "task_max_retries_exceeded")).toBe(false);
  });
});

