      if (task.depends_on.some((dep) => !doneSet.has(dep))) continue;

      // Criterion 3 + 4: task.repo must be a repo in this workspace (which is watched)
      if (!reachableRepoIds.has(task.repo)) continue;

      // Criterion 5: all required skills must exist in the workflow repo or workspace-local .claude/skills/
      const missing = requiredSkills.filter(
        (slug) => !skillDirExists(workflowRoot, workspaceRoot, slug),
      );
      if (missing.length > 0) {
        emitSkippedMissingSkill({
          type: "task_skipped_missing_skill",
          taskId: task.id,
          featureId,
          missingSkills: missing,
        });
        continue;
      }

      eligible.push({ task, featureId });
    }
  }

  // ── 6. Deterministic ordering ───────────────────────────────────────────
  // Sort ascending by numeric task ID (T1 < T5 < T10).
  eligible.sort((a, b) => taskNumericId(a.task.id) - taskNumericId(b.task.id));

  return eligible;
}

/**
 * Find all tasks eligible for a fix agent (status=change_requested with a PR URL).
 * Live state is read from the feature branch when available.
 */
export function findFixableTasks(
  agentConfig: AgentConfig,
  workspaceRoot: string,
