 * Returned by checkInReviewPrs so the main loop can retry the merge.
 */
export interface WorkspacePrRecovery {
  taskId: string;
  featureId: string;
  workspaceRoot: string;
  /** URL of the management-repo PR that needs to be merged. */
  workspacePrUrl: string;
}

